import os,time
from concurrent.futures import ThreadPoolExecutor
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
k=os.urandom(16);n=os.urandom(16);
ex=ThreadPoolExecutor(12)
d=os.urandom(1<<20); mv=memoryview(d)
outs=[bytearray(len(d)+16) for _ in range(12)]
def w(i):
  e=Cipher(algorithms.AES(k),modes.CTR(n)).encryptor()
  for r in range(20): e.update_into(mv, outs[i])
def g(i):
  a=AESGCM(k)
  for r in range(20): a.encrypt(n[:12],mv,None)
for f in (w,g):
 for T in (1,6,12):
  t=time.perf_counter(); list(ex.map(f,range(T))); print(f.__name__,T,(time.perf_counter()-t)/T)
